import{_ as a,o as t,c as r,a0 as o}from"./chunks/framework.DZqO77tS.js";const m=JSON.parse('{"title":"Let’s get started","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/hack/getting-started.md","filePath":"en/docs/hack/getting-started.md"}'),i={name:"en/docs/hack/getting-started.md"};function n(s,e,l,c,h,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="let-s-get-started" tabindex="-1">Let’s get started <a class="header-anchor" href="#let-s-get-started" aria-label="Permalink to &quot;Let’s get started&quot;">​</a></h1><p>Welcome! This page takes you, in about 15–20 minutes, to <strong>reading sensor data with EcoCONNECT</strong>.</p><h2 id="you-will-need" tabindex="-1">You will need <a class="header-anchor" href="#you-will-need" aria-label="Permalink to &quot;You will need&quot;">​</a></h2><ul><li>An EcoCONNECT main board (assembled)</li><li>A Micro-USB cable</li><li>A computer (Windows / macOS / Linux)</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-connect-the-ecoconnect-main-board-to-your-pc" tabindex="-1">1. Connect the EcoCONNECT main board to your PC <a class="header-anchor" href="#_1-connect-the-ecoconnect-main-board-to-your-pc" aria-label="Permalink to &quot;1. Connect the EcoCONNECT main board to your PC&quot;">​</a></h3><p>Connect the EcoCONNECT main board to the PC with a Micro-USB cable. When it connects, the power LED blinks once. <a href="#">Where the EcoCONNECT connectors are</a></p><h3 id="_2-flash-the-ready-made-firmware" tabindex="-1">2. Flash the ready-made firmware <a class="header-anchor" href="#_2-flash-the-ready-made-firmware" aria-label="Permalink to &quot;2. Flash the ready-made firmware&quot;">​</a></h3><p>EcoCONNECT includes a <strong>firmware image</strong> you can use without writing code first.</p><ol><li>Open <code>firmware/pico2/release/</code> in the repository.</li><li>Follow the README in <code>firmware/pico2/</code> and copy the <code>.uf2</code> onto the Raspberry Pi Pico.</li><li>When the board reboots, you are ready for the first reading.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Do not unplug the USB cable while flashing.</p></div><h3 id="_3-read-the-sensor-values" tabindex="-1">3. Read the sensor values <a class="header-anchor" href="#_3-read-the-sensor-values" aria-label="Permalink to &quot;3. Read the sensor values&quot;">​</a></h3><p>Open a terminal and run the sensor-reading program.</p><h3 id="_4-going-further" tabindex="-1">4. Going further <a class="header-anchor" href="#_4-going-further" aria-label="Permalink to &quot;4. Going further&quot;">​</a></h3><p>You can now use sensor values on your PC. Next: <a href="/AuraLinc-Community/en/docs/hack/remote">Send data wirelessly</a>.</p><h2 id="other-resources" tabindex="-1">Other resources <a class="header-anchor" href="#other-resources" aria-label="Permalink to &quot;Other resources&quot;">​</a></h2><ul><li>A <a href="/AuraLinc-Community/en/steam/recipes">recipe</a> you can finish in about 10 minutes</li><li><a href="/AuraLinc-Community/en/steam/examples">Examples</a> for ideas</li><li>For teachers: <a href="/AuraLinc-Community/en/steam/">Workshop materials</a></li></ul>',17)])])}const p=a(i,[["render",n]]);export{m as __pageData,p as default};
